; ==============================================================================
; Technics SX-WSA1R -- prom_c (CPU 2, IC28) -- 0xF80000-0xF97FFF  THE PRESET BANK
; ==============================================================================
;
; 9,310 lines moved out of prom_c/wsa1_prom_c.s by notes/prom_c_split.py.  The master
; `.include`s this file at the line the block started on, so the assembler
; sees the same token stream in the same order and the ROM is unchanged:
;
;     python3 scripts/analysis/assert_byte_identical.py    <- the bytes
;     python3 notes/prom_c_split.py --verify               <- the text
;
; ★ EVERY LINE BELOW THIS HEADER IS VERBATIM.  Nothing was reworded, and
;   --verify fails on a single changed character.
;
; WHY THIS IS ONE SUBJECT:
; One generated data object: 32-byte header, 16 category names, 129 fixed
; 704-byte records.  Its own banner states the geometry and the four
; independent facts it rests on.  No consumer has been located, so this is
; filed as DATA, not under a subsystem that would claim to read it.
; ⚠ RETRACTED 2026-09-25: a consumer HAS been located -- CPU 1 reads it over the
; link; see READERS in the banner below.
;
; >>> END OF EXTRACTION HEADER -- everything below is verbatim from the master

; ==============================================================================
; 0xF80000-0xF97FFF -- THE PRESET BANK  (98,304 bytes)
; ==============================================================================
;
; Generated by notes/gen_prom_c_preset_bank.py -- every number below is read out of
; the ROM, never retyped.  `python3 notes/gen_prom_c_preset_bank.py --verify`
; re-proves all of it and exits non-zero on any failure.
;
; A 32-byte header with the ASCII magic `ZZZZ`, a table of 16 sixteen-byte CATEGORY
; names, and 129 fixed 704-byte RECORDS each opening with a 16-character name.
;
; ★ THE GEOMETRY RESTS ON FOUR INDEPENDENT FACTS, and a wrong constant breaks each:
;   1. TILING -- 129 x 704 from 0xF80300 reaches 0xF965C0 exactly, and 0xF965C0 is
;      precisely the first byte of the image's trailing 0x0E pad (the byte before it
;      is 0xFF, so the boundary is not chosen).
;   2. SELF-TERMINATION -- inside every record the walk {tag, length, length bytes}
;      from +0x000 lands on tag 0xFF / length 0xFF at +0x2BE, which puts the record
;      end at +0x2C0 = 704.  The stride is readable from ONE record.
;   3. THE HEADER AGREES -- u32le at 0xF8001C is 0x02C0 = 704, and its two directory
;      entries give (offset 0x000200, count 16) and (offset 0x000300, count 128).
;      16 x 16 tiles 0xF80200..0xF802FF; 128 x 704 tiles 0xF80300..0xF962FF, and the
;      129th record -- the one named `Clear` -- follows it.
;   4. UNIFORM LAYOUT -- all 129 records yield the SAME 24 (offset, tag, length)
;      triples.  One desynchronised record would produce a different list.
;
; ⚠ WHAT IS **NOT** ESTABLISHED.
;   * NO INSTRUCTION THAT READS THIS REGION HAS BEEN FOUND.  A search of all four
;     images for a 32-bit pointer into 0xF80000-0xF97FFF gives 21 hits in prom_c, and
;     `--refs` classifies every one against THIS FILE'S disassembly: NONE is a real
;     instruction operand -- 8 fall inside instructions that render something else,
;     13 are in data regions.  The word `preset` comes from the ASCII the region
;     contains, not from a consumer.
;   * NOT ONE FIELD MEANING is established.  `--census` prints the value census of
;     every byte position of every chunk; that is a fact about the format, not a name
;     for a parameter.  Nothing below is called pitch, level or wave.
;   * The directory-entry field split is AMBIGUOUS: {u16 id, u32le offset, u16 count}
;     and {u16 id, u16 offset, u16 zero, u16 count} give identical bytes here.
;
; ⚠⚠ RETRACTED 2026-09-25 (lane promcd) -- THE FIRST TWO BULLETS ABOVE ARE FALSE (the
;   third, the directory-entry ambiguity, still stands).  They are kept verbatim so the
;   record of what was believed survives; do not quote them.
;
; ★ READERS.  CPU 1 reads this region over the inter-processor link.  The pointer search
;   above discarded prom_a's hits as ambiguous; the readers ARE those hits.  Six prom_a
;   routines build an address in CPU 2's space from this region's own constants and hand
;   it to Link_SendCommandE2 (prom_a 0xF8E0FE, via prom_b thunk 0xF40EF0), the 0xE2
;   REMOTE READ whose frame is (remote address, length, local buffer):
;     CombiBank_RemoteCombiAddr (0xF9F984)  mode 0: 0xF80300 + 0x1600*bank + 0x2C0*memory, bank 0..15,
;                            memory 0..7 (mode 8: CPU 2 flash 0xEC0300, the USER bank;
;                            mode 0x10: a RAM working copy at 0xC00300)
;     CombiBank_RemoteGroupNameAddr (0xF9F910)  mode 0: 0xF80200 + 0x10*bank -- PresetBank_CategoryNames,
;                            indexed by the bank alone: 16 names for 16 banks of 8
;     Combination_ReadFromCpu2 (0xF98927)  0xF80300 + 0x2C0*index, 0x2C0 bytes -> CPU 1 RAM 0x7620
;     sub_FAABB3 (0xFAABB3)  0xF80300 itself (combination 0), 0x2C0 bytes -> CPU 1 RAM 0x7300
;     sub_FC1C77 (0xFC1C77)  0xF80300 + 0x2C0*index + 2, 16 bytes -> 0x810: the NAME alone
;     sub_FC21D0 (0xFC21D0)  base 0xF80000 (loaded by sub_FC2155) + 0x200 + 0x10*bank,
;                            16 bytes -> 0x810: one bank name
;   So the record stride 0x2C0 = 704 and the bank stride 0x1600 = 8 x 704 are the
;   READERS' constants, not only the data's; CombiBank_RemoteCombiAddr's three branches (0xF80300,
;   0xF8F500, 0xF90B00) are one linear array, 0xF8F500 = 0xF80300 + 11*0x1600 exactly.
;
; ★ WHAT IT IS.  The factory COMBINATION memory: 16 banks x 8 combinations, the same
;   format as the SysEx COMBINATION bulk-dump category (ADR 50 00 00), whose first block's
;   16-byte signature 5A 5A 5A 5A 00 00 57 53 41 31 20 20 01 00 00 02 is this region's
;   first 16 bytes, and whose 0x300-byte header block is 0xF80000-0xF802FF.  The user
;   bank (mode 8) has the same shape, names 0x100 below the data at 0xEC0200.
;   Each tag is the instrument's own parameter-record number (the same number that
;   addresses the record in a parameter message), so the chunk table above reads:
;     0x78 COMBINATION NAME   0x60 EFFECT COMMON   0x61 EFFECT block 1   0x62 EFFECT block 2
;     0x63 REVERB block       0x00+k / 0x20+k  PART k+1, individual blocks A / B
;     0x92 KEY SCALING / SCALE TUNING              0x79 PART COMMON (real time)
;   Field-level names (PROGRAM CHANGE & BANK at A+0x00, VOLUME at A+0x03, PANPOT at
;   A+0x08, KEY LAYER LOW/HIGH at B+0x07/+0x08 ...) and the range checks that pin them
;   over all 129 presets: `python3 wsa1/notes/sysex-probes/sysex_combination_layout.py
;   --fields`.  Corroboration from CPU 1's use: 0xFAAB86-0xFAABA6 takes the first payload
;   byte of each effect record out of the copy at 0x7620 (0x7642 / 0x7662 / 0x7682 =
;   0x7620 + 0x22 / 0x42 / 0x62) and passes it with the record number 0x61 / 0x62 / 0x63
;   to prom_b 0xF42F58 -- the effect TYPE, where the reference puts it.
;   The ONE FIELD below is thereby named: payload +0x0D of an A block (tags 0x00..0x07)
;   is BASIC CHANNEL in bits 0-4, LOCAL CONTROL bit 5, MIDI OUT SETTING bit 6, MIDI IN
;   SETTING bit 7 (--fields).  Its low nibble equals the tag because each factory part k
;   is on basic channel k; the high nibble 0xC / 0xE is LOCAL CONTROL off / on, which
;   supersedes the [INFERENCE] "in-use flag" below.
;   Every instruction byte above is asserted by
;   `python3 notes/lanes/promcd-2026-09-25/preset_bank_readers.py`; the reference is
;   wsa1/docs/system-exclusive-reference/sec-blocks.tex, "Inside the COMBINATION block".
;
; ★ ONE FIELD IS PROVEN, and it is what makes the eight paired blocks an indexed
; array rather than eight unrelated chunks: in ALL 1,032 blocks tagged 0x00..0x07
; (129 records x 8) the payload byte at +13 has LOW NIBBLE equal to the block's own
; tag, and its high nibble takes only 0xC and 0xE.  The record named `Clear` is the
; only one of the 129 whose eight blocks are all 0xE.  [INFERENCE, stated as such]
; that reads like an in-use flag; nothing here proves it.
;
; PROVENANCE unchanged: the publicly redistributed v2 firmware set, not a chip read.
wsa1_prom_c:
; Evidence: the whole-region name for the block argued at length in the banner above and
;           in notes/FINDINGS-prom_c-preset-bank.md; re-proved by
;           `python3 notes/gen_prom_c_preset_bank.py --verify`.  (⚠ ADDED 2026-08-25:
;           notes/prom_c_header_audit.py rated this the image's ONE tier-C label -- a name
;           with nothing directly above it -- because the banner ends four lines earlier.)
PresetBank:
; ----------------------------------------------------------------------------
; PresetBank_Header -- 0xF80000..0xF8001F  (32 bytes)
; ----------------------------------------------------------------------------
; The COMBINATION block header.  Its first 16 bytes equal the signature the SysEx
; reference prints for bulk-dump block COMBINATION 1 (ADR 50 00 00), read from a
; real instrument's dump (wsa1/docs/system-exclusive-reference/tbl-signatures.tex).
; Its fields are not read as fields: sub_FC2155 (0xFC2155) loads 0xF80000 as the
; block base and sub_FC21D0 adds the constant 0x200, and the combination readers
; carry 0x300 and 0x2C0 as constants too -- the same values directory entries 1 and
; 2 and the stride word below hold.
PresetBank_Header:
	.ascii	"ZZZZ"
	.short	0x0000
	.ascii	"WSA1  "
	; directory entry 0 -- the category-name table
	.short	0x0001                                 ; id
	.short	0x0200, 0x0000                         ; offset 0x000200 (u32le), or offset+0 (two u16)
	.short	0x0010                                 ; count 16
	; directory entry 1 -- the record array
	.short	0x0002                                 ; id
	.short	0x0300, 0x0000                         ; offset 0x000300 (u32le), or offset+0 (two u16)
	.short	0x0080                                 ; count 128
	.short	0x02c0, 0x0000                         ; 704 == the record stride

; ----------------------------------------------------------------------------
; PresetBank_HeaderPad -- 0xF80020..0xF801FF  (480 bytes, all zero)
; ----------------------------------------------------------------------------
PresetBank_HeaderPad:
	.fill 0x1E0, 1, 0x00

; ----------------------------------------------------------------------------
; PresetBank_CategoryNames -- 0xF80200..0xF802FF  (16 x 16 bytes)
; ----------------------------------------------------------------------------
; Bank names, 16 bytes each, one per bank of eight combinations.  Read by prom_a
; CombiBank_RemoteGroupNameAddr (0xF9F910) as 0xF80200 + 0x10*bank and by sub_FC21D0 (0xFC21D0) as
; 0xF80000 + 0x200 + 0x10*bank, remote-read over the link (see READERS above).
PresetBank_CategoryNames:
	.ascii	"FUSION COMBO1   "	; [ 0]
	.ascii	"JAZZ COMBO      "	; [ 1]
	.ascii	"WILD WORLD      "	; [ 2]
	.ascii	"HAPPY TIME      "	; [ 3]
	.ascii	"STRING ORCHESTRA"	; [ 4]
	.ascii	"ORCHESTRAL      "	; [ 5]
	.ascii	"VOCAL & ORGAN   "	; [ 6]
	.ascii	"BIG BAND        "	; [ 7]
	.ascii	"PIANO PAD       "	; [ 8]
	.ascii	"PERCUSSIVE PAD  "	; [ 9]
	.ascii	"ENSEMBLE PAD    "	; [10]
	.ascii	"SWEEP PAD       "	; [11]
	.ascii	"GUITAR STACK    "	; [12]
	.ascii	"SYNTH STACK     "	; [13]
	.ascii	"ROCK STAFF      "	; [14]
	.ascii	"DRUM & EFFECT   "	; [15]

; ----------------------------------------------------------------------------
; PresetBank_Records -- 0xF80300..0xF965BF  (129 x 704 = 90816 bytes)
; ----------------------------------------------------------------------------
; Every record is the same chain of chunks {u8 tag, u8 length, length bytes}:
;     +0x000  tag 0x78  length    16   16-character ASCII name
;     +0x012  tag 0x60  length    12   12 bytes; only byte 0 differs between records (0 in 116, 1 in 13)
;     +0x020  tag 0x61  length    30   30 bytes; bytes 23..29 are zero in every record
;     +0x040  tag 0x62  length    30   30 bytes; bytes 23..29 are zero in every record
;     +0x060  tag 0x63  length    30   30 bytes; bytes 23..29 are zero in every record
;     +0x080  tag 0x00  length    30   block 0, first of the pair
;     +0x0A0  tag 0x20  length    30   block 0, second of the pair
;     +0x0C0  tag 0x01  length    30   block 1, first of the pair
;     +0x0E0  tag 0x21  length    30   block 1, second of the pair
;     +0x100  tag 0x02  length    30   block 2, first of the pair
;     +0x120  tag 0x22  length    30   block 2, second of the pair
;     +0x140  tag 0x03  length    30   block 3, first of the pair
;     +0x160  tag 0x23  length    30   block 3, second of the pair
;     +0x180  tag 0x04  length    30   block 4, first of the pair
;     +0x1A0  tag 0x24  length    30   block 4, second of the pair
;     +0x1C0  tag 0x05  length    30   block 5, first of the pair
;     +0x1E0  tag 0x25  length    30   block 5, second of the pair
;     +0x200  tag 0x06  length    30   block 6, first of the pair
;     +0x220  tag 0x26  length    30   block 6, second of the pair
;     +0x240  tag 0x07  length    30   block 7, first of the pair
;     +0x260  tag 0x27  length    30   block 7, second of the pair
;     +0x280  tag 0x92  length    14   14 bytes, IDENTICAL in all 129 records
;     +0x290  tag 0x79  length    44   44 bytes; only byte 5 differs, and in one record only
;     +0x2BE  tag 0xFF  length   --    end marker
; The eight blocks tagged 0x00..0x07 each carry their own index in payload[13] &
; 0x0F (checked for all 1,032); the blocks tagged 0x20..0x27 are their partners by
; position, which is what the alternating layout shows and all that it shows.
;
; ★ ROUND 4 -- THE 129 RECORD LABELS NOW CARRY THE RECORD'S OWN NAME.  Each was
; PresetBank_Record_NNN, a kind plus an index; each is now the 16-character ASCII
; string the record itself begins with, mangled to an identifier (spaces and
; punctuation to '_', '&' to 'And', apostrophes dropped).  Nothing is invented:
; the name is chunk 0x78's payload at record+2, which this file already printed in
; the comment above every label, and the 129 strings are distinct before AND after
; mangling.  Regenerate and re-verify all 129 against the ROM -- including the last,
; record 128, which is the template and is named 'Clear' -- with
;     python3 notes/prom_c_understanding_round4.py --presets
; ⚠ The record INDEX is no longer in the label.  It is still in the comment line
; directly above each one, which is where the address is too.
PresetBank_Records:
; ............................................................................
; record 0 -- 0xF80300  '  Downtown Set  '
; preset combination: bank 0 'FUSION COMBO1', memory 0.  Read by prom_a CombiBank_RemoteCombiAddr as 0xF80300 + 0x1600*0 + 0x2C0*0
; and by Combination_ReadFromCpu2 as index 0; remote-read to CPU 1 (READERS above).
